struct KepElems
{
    // Keplerian elements
    double a; // Semi-major axis                    (au)
    double e; // Eccentricity
    double I; // Inclination                        (deg)
    double M; // Mean anomaly                       (deg)
    double w; // Argument of periapsis              (deg)
    double O; // Longitude of the ascending node    (deg)
};

struct KepRates
{
    // Keplerian rates
    double da; // (au/century)
    double de;
    double dI; // (deg/century)
    double dM; // (deg/century)
    double dw; // (deg/century)
    double dO; // (deg/century)
};

struct KepExtra
{
    double b;
    double c;
    double s;
    double f;
};

struct Header
{
    int STAR0;
    int STAR1;
    int STARN;
    int STNUM;
    bool MPROP;
    int NMAG;
    int NBENT;
};

struct Entry
{
    float XNO;
    double SRA0;
    double SDEC0;
    char IS[2];
    float MAG;
    double XRPM;
    float XDPM;
};

struct Conf
{
    double longitude;
    double latitude;
    const char *dt_string_utc;
    float threshold;
    float label_thresh;
    int fps;
    float speed;
    double julian_date;
    double aspect_ratio;
    bool quit_on_any;
    bool unicode;
    bool color;
    bool grid;
    bool constell;
    bool metadata;
};

struct ObjectBase
{
    double azimuth; // Coordinates used for rendering
    double altitude;
    int color_pair; // 0 indicates no color pair
    char symbol_ASCII;
    const char *symbol_unicode;
    const char *label;
};

struct Star
{
    struct ObjectBase base;
    int catalog_number;
    double right_ascension;
    double declination;
    double ra_motion;
    double dec_motion;
    float magnitude;
};

struct Planet
{
    struct ObjectBase base;
    const struct KepElems *elements;
    const struct KepRates *rates;
    const struct KepExtra *extras;
    float magnitude;
};

struct Moon
{
    struct ObjectBase base;
    const struct KepElems *elements;
    const struct KepRates *rates;
    float magnitude;
};

struct Constell
{
    unsigned int num_segments;
    int *star_numbers;
};

struct SwTimestamp
{
    // Timestamp value
    union {
#ifdef _WIN32
        LARGE_INTEGER tick_win;
#endif
        unsigned long long tick_apple;
        struct timespec tick_spec;
        struct timeval tick_val;
    } val;

    // Holds most recently set union member as a sanity check
    enum
    {
        TICK_WIN,
        TICK_APPLE,
        TICK_SPEC,
        TICK_VAL,
    } val_member;
};

typedef struct
{
    const char *city_name;
    float latitude;
    float longitude;
} CityData;

