        + std::to_string(year) + " "
        + (hour12<10?"0":"") + std::to_string(hour12) + ":"
        + (minute<10?"0":"") + std::to_string(minute) + ":"
        + (second<10?"0":"") + std::to_string(second) + " " + ampm;
