import random
import struct
from typing import List

# This generator produces valid little-endian binary buffers where
# the first N bytes are interpretable as a primitive value.
# It targets the following stub expectations:
# - requires at least 2/4/8 bytes for various converters
# - prefers interesting boundary and special values (e.g., min/max ints, NaN/Inf for floats)
# - buffer can be longer than minimum; stubs only read the prefix
# Keep total size <= 4096 bytes.

# Precompute interesting values for each width and type to trigger diverse code paths.

INT16_VALUES: List[int] = [
    0, 1, -1, 127, -128, 255, -255, 256, -256, 32767, -32768
]
UINT16_VALUES: List[int] = [
    0, 1, 0x7FFF, 0x8000, 0xFFFF, 255, 256
]

INT32_VALUES: List[int] = [
    0, 1, -1, 2**15-1, -(2**15), 2**31-1, -(2**31), 2**16, -(2**16), 123456789, -123456789
]
UINT32_VALUES: List[int] = [
    0, 1, 0x7FFFFFFF, 0x80000000, 0xFFFFFFFF, 65535, 65536, 1234567890
]

INT64_VALUES: List[int] = [
    0, 1, -1, 2**31-1, -(2**31), 2**63-1, -(2**63), 2**32, -(2**32), 0x7FFFFFFFFFFFFFFF, -0x8000000000000000
]
UINT64_VALUES: List[int] = [
    0, 1, 0x7FFFFFFFFFFFFFFF, 0x8000000000000000, 0xFFFFFFFFFFFFFFFF, 2**32-1, 2**32
]

# Interesting float32 patterns (as Python floats). We will pack as little-endian.
FLOAT32_VALUES: List[float] = [
    0.0, -0.0, 1.0, -1.0, 0.5, -0.5, 3.1415927, float('inf'), float('-inf')
]
# Add a specific quiet NaN with payload via raw bits to guarantee NaN representation.
FLOAT32_NAN_BITS = 0x7FC00001

# Interesting float64 patterns.
DOUBLE64_VALUES: List[float] = [
    0.0, -0.0, 1.0, -1.0, 0.5, -0.5, 3.141592653589793, 1e-300, 1e300, float('inf'), float('-inf')
]
DOUBLE64_NAN_BITS = 0x7FF8000000000001

# Bool32: choose canonical false/true and some non-zero edge values
BOOL32_VALUES: List[int] = [0, 1, 2, 0xFFFFFFFF, 0x80000000]


def _pack_le_int(value: int, byte_width: int) -> bytes:
    if byte_width == 2:
        return value.to_bytes(2, 'little', signed=True)
    if byte_width == 4:
        return value.to_bytes(4, 'little', signed=True)
    if byte_width == 8:
        return value.to_bytes(8, 'little', signed=True)
    raise ValueError('unsupported width')


def _pack_le_uint(value: int, byte_width: int) -> bytes:
    return value.to_bytes(byte_width, 'little', signed=False)


def _pack_le_float32(value: float) -> bytes:
    return struct.pack('<f', value)


def _pack_le_double64(value: float) -> bytes:
    return struct.pack('<d', value)


def _pack_raw_bits_u32(bits: int) -> bytes:
    return struct.pack('<I', bits & 0xFFFFFFFF)


def _pack_raw_bits_u64(bits: int) -> bytes:
    return struct.pack('<Q', bits & 0xFFFFFFFFFFFFFFFF)


def _random_tail(rng: random.Random, max_tail: int) -> bytes:
    # Append a random-length tail of random bytes (possibly empty) to exercise stubs that ignore extra bytes.
    if max_tail <= 0:
        return b''
    length = rng.randint(0, max_tail)
    if length == 0:
        return b''
    return rng.randbytes(length)


def _choose_prefix(rng: random.Random) -> bytes:
    # Randomly choose one of the target width/type families, then pick an interesting value.
    choice = rng.choices(
        population=['i16','u16','i32','u32','i64','u64','f32','f64','b32'],
        weights=[2,2,3,3,3,3,3,3,2],
        k=1
    )[0]

    if choice == 'i16':
        v = rng.choice(INT16_VALUES)
        return _pack_le_int(v, 2)
    if choice == 'u16':
        v = rng.choice(UINT16_VALUES)
        return _pack_le_uint(v, 2)
    if choice == 'i32':
        v = rng.choice(INT32_VALUES)
        return _pack_le_int(v, 4)
    if choice == 'u32':
        v = rng.choice(UINT32_VALUES)
        return _pack_le_uint(v, 4)
    if choice == 'i64':
        v = rng.choice(INT64_VALUES)
        return _pack_le_int(v, 8)
    if choice == 'u64':
        v = rng.choice(UINT64_VALUES)
        return _pack_le_uint(v, 8)
    if choice == 'f32':
        # Occasionally emit NaN via raw bits to ensure NaN coverage
        if rng.random() < 0.3:
            return _pack_raw_bits_u32(FLOAT32_NAN_BITS)
        v = rng.choice(FLOAT32_VALUES)
        return _pack_le_float32(v)
    if choice == 'f64':
        if rng.random() < 0.3:
            return _pack_raw_bits_u64(DOUBLE64_NAN_BITS)
        v = rng.choice(DOUBLE64_VALUES)
        return _pack_le_double64(v)
    if choice == 'b32':
        v = rng.choice(BOOL32_VALUES)
        return _pack_le_uint(v, 4)

    # Fallback (should not happen)
    return _pack_le_uint(0, 4)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Build a valid buffer: ensure it meets at least the smallest requirement (>=2 bytes)
    # and often one of 4 or 8 so other stubs run frequently.
    prefix = _choose_prefix(rng)

    # Decide on a total length cap. Stubs only need the first N bytes, but we can add a tail up to 256 bytes.
    # Keep global max under 4096 bytes.
    max_tail = min(256, 4096 - len(prefix))

    # Occasionally pad to exactly the minimum for that width to test boundary, otherwise add random tail.
    if rng.random() < 0.5:
        tail = b''
    else:
        tail = _random_tail(rng, max_tail)

    buf = prefix + tail

    # Ensure at least 2 bytes (always true given prefix), but be defensive
    if len(buf) < 2:
        buf += b"\x00\x00"

    return buf
